/** Unknown/uploaded avatars keep their existing image-box boundary. */
export function avatarCrownTop(source: string | null | undefined): number {
  const file =
    source && /\/avatars\/table\/((?:free|vip)_[\w-]+(?:@2x)?\.webp)(?:[?#]|$)/.exec(source)?.[1];
  return (file && AVATAR_CROWN_TOP[file]) || 0;
}

/** Project the measured visible crown through the image's rendered scale. */
export function paintedAvatarTop(image: HTMLImageElement): number {
  const box = image.getBoundingClientRect();
  return box.top + box.height * avatarCrownTop(image.currentSrc || image.src);
}

/**
 * Seat placement must not capture a breathing/gesture frame. Project the
 * image's static bust framing from layout coordinates instead. The visible
 * avatar keeps playing every animation; only its pod's baseline is stable.
 */
export function avatarRestPose(image: HTMLElement): string {
  const wrap = image.closest<HTMLElement>('.seat__avatar-wrap');
  return wrap ? getComputedStyle(wrap).getPropertyValue('--sp-avatar-rest-transform').trim() : '';
}

export function restingAvatarTop(image: HTMLImageElement, scale: number): number {
  const seat = image.closest<HTMLElement>('.seat');
  const wrap = image.closest<HTMLElement>('.seat__avatar-wrap');
  if (!seat || !wrap || !image.offsetHeight) return paintedAvatarTop(image);
  let y = image.offsetHeight * avatarCrownTop(image.currentSrc || image.src);
  let element: HTMLElement | null = image;
  while (element && element !== seat) {
    const style = getComputedStyle(element);
    // The image owns permanent bust scale/clip. Ancestors own temporary
    // active/winner scales and gestures, never the pod's resting geometry.
    const transform =
      element === image ? style.transform : element === wrap ? avatarRestPose(image) : '';
    if (transform && transform !== 'none') {
      const matrix = new DOMMatrix(transform);
      const originY = parseFloat(style.transformOrigin.split(' ')[1]) || 0;
      y = originY + (y - originY) * matrix.d + matrix.f;
    }
    // Opponent artwork uses an individual paint scale on the avatar frame.
    // It composes outside the image bust transform and must participate in
    // static crown projection; default/hero frames retain scale 1.
    if (element.matches('.seat__avatar')) {
      const axes = (style.scale || 'none').trim().split(/\s+/).map(Number);
      const permanentScale = axes[1] ?? axes[0];
      if (Number.isFinite(permanentScale) && permanentScale > 0) {
        const originY = parseFloat(style.transformOrigin.split(' ')[1]) || 0;
        y = originY + (y - originY) * permanentScale;
      }
    }
    const parent = element.offsetParent as HTMLElement | null;
    y += element.offsetTop + (parent?.clientTop || 0);
    element = parent;
  }
  // Detached/non-seat fixtures retain their rendered-box projection.
  return element === seat ? seat.getBoundingClientRect().top + y * scale : paintedAvatarTop(image);
}

// Table character positions and sizes stay fixed through turn/winner states.
// Keep this shared projection contract explicit: only the static bust transform
// and opponent normalization scale contribute to permanent artwork geometry.
const avatarFocusScale = (_image: HTMLElement) => 1;
const seatFocusScale = (_image: HTMLElement) => 1;

export function permanentAvatarFocusScale(_image: HTMLElement): number {
  return 1;
}

/** Permanent image rectangle for wager ownership, excluding compositor gestures. */
export function restingAvatarBox(image: HTMLElement, scale: number): DOMRect {
  const seat = image.closest<HTMLElement>('.seat');
  const wrap = image.closest<HTMLElement>('.seat__avatar-wrap');
  if (!seat || !wrap || !image.offsetWidth || !image.offsetHeight)
    return image.getBoundingClientRect();
  const points = [
    [0, 0],
    [image.offsetWidth, 0],
    [0, image.offsetHeight],
    [image.offsetWidth, image.offsetHeight],
  ];
  let element: HTMLElement | null = image;
  while (element && element !== seat) {
    const style = getComputedStyle(element);
    const origin = style.transformOrigin.split(/\s+/).map(parseFloat);
    const ox = origin[0] || 0,
      oy = origin[1] || 0;
    const transform =
      element === image ? style.transform : element === wrap ? avatarRestPose(image) : '';
    if (transform && transform !== 'none') {
      const m = new DOMMatrix(transform);
      for (const point of points) {
        const x = point[0] - ox,
          y = point[1] - oy;
        point[0] = ox + x * m.a + y * m.c + m.e;
        point[1] = oy + x * m.b + y * m.d + m.f;
      }
    }
    if (element.matches('.seat__avatar')) {
      const axes = (style.scale || 'none').split(/\s+/).map(Number);
      const focus = avatarFocusScale(image);
      const sx = (Number.isFinite(axes[0]) && axes[0] > 0 ? axes[0] : 1) * focus;
      const axisY = axes[1] ?? axes[0];
      const sy = (Number.isFinite(axisY) && axisY > 0 ? axisY : 1) * focus;
      if (Number.isFinite(sx) && sx > 0)
        for (const point of points) {
          point[0] = ox + (point[0] - ox) * sx;
          point[1] = oy + (point[1] - oy) * sy;
        }
    }
    const parent = element.offsetParent as HTMLElement | null;
    for (const point of points) {
      point[0] += element.offsetLeft + (parent?.clientLeft || 0);
      point[1] += element.offsetTop + (parent?.clientTop || 0);
    }
    element = parent;
  }
  if (element !== seat) return image.getBoundingClientRect();
  const base = seat.getBoundingClientRect();
  const ratio = scale * seatFocusScale(image);
  const xs = points.map((p) => base.left + p[0] * ratio),
    ys = points.map((p) => base.top + p[1] * ratio);
  return new DOMRect(
    Math.min(...xs),
    Math.min(...ys),
    Math.max(...xs) - Math.min(...xs),
    Math.max(...ys) - Math.min(...ys)
  );
}

/** Permanent action badge keepout, independent of its owed pop-in animation.
 * Actions are direct, absolutely positioned seat children. The layout coordinates
 * and individual translate remain permanent; only the animated transform is
 * replaced by its resting translateX(-50%). No painted element is changed.
 */
export function restingActionBox(action: HTMLElement, scale: number): DOMRect {
  const seat = action.closest<HTMLElement>('.seat');
  if (!seat || action.offsetParent !== seat) return action.getBoundingClientRect();
  const style = getComputedStyle(action);
  const width = parseFloat(style.width),
    height = parseFloat(style.height);
  if (!(width > 0 && height > 0)) return action.getBoundingClientRect();
  const used = (value: string, basis: number, fallback: number): number => {
    const amount = parseFloat(value);
    return Number.isFinite(amount)
      ? amount * (value.trim().endsWith('%') ? basis / 100 : 1)
      : fallback;
  };
  const translate = (style.translate || 'none').trim().split(/\s+/);
  const x =
    used(style.left, seat.clientWidth, action.offsetLeft) +
    used(translate[0], width, 0) -
    width / 2 +
    seat.clientLeft;
  const y =
    used(style.top, seat.clientHeight, action.offsetTop) +
    used(translate[1] || '0', height, 0) +
    seat.clientTop;
  const base = seat.getBoundingClientRect();
  return new DOMRect(base.left + x * scale, base.top + y * scale, width * scale, height * scale);
}

/** Project CSS layout pixels without turning fractional widths into a scale. */
export function tableRenderScale(element: HTMLElement): number {
  const style = getComputedStyle(element);
  let width = parseFloat(style.width);
  if (style.boxSizing !== 'border-box')
    for (const name of [
      'paddingLeft',
      'paddingRight',
      'borderLeftWidth',
      'borderRightWidth',
    ] as const)
      width += parseFloat(style[name]) || 0;
  const layoutWidth = width > 0 ? width : element.offsetWidth;
  const scale = element.getBoundingClientRect().width / layoutWidth;
  return Number.isFinite(scale) && scale > 0 ? scale : 1;
}
